import os
import hmac
import hashlib
import time
from flask import Flask, request, jsonify, abort
import xml.etree.ElementTree as ET
import requests

app = Flask(__name__)

INTERNAL_SERVICE_URL = os.environ.get('INTERNAL_SERVICE_URL', 'http://internal-api:8080')
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def verify_webhook_signature(payload, signature):
    """Verify incoming webhook signature - timing safe comparison"""
    expected = hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/api/v1/import', methods=['POST'])
def import_data():
    """Import data from partner XML feed"""
    content_type = request.headers.get('Content-Type', '')
    if 'xml' not in content_type and 'text' not in content_type:
        return jsonify({'error': 'Content-Type must be XML'}), 415

    raw_body = request.get_data()
    if len(raw_body) > 10 * 1024 * 1024:  # 10MB limit
        return jsonify({'error': 'Payload too large'}), 413

    try:
        # Parse the XML document
        root = ET.fromstring(raw_body)
    except ET.ParseError as e:
        return jsonify({'error': f'XML parse error: {str(e)}'}), 400

    records = []
    for item in root.findall('.//record'):
        record = {}
        for child in item:
            record[child.tag] = child.text
        records.append(record)

    if not records:
        return jsonify({'error': 'No records found in XML'}), 422

    # Forward parsed records to internal processing service
    try:
        resp = requests.post(
            f"{INTERNAL_SERVICE_URL}/process",
            json={'records': records, 'source': 'partner_feed'},
            timeout=30
        )
        resp.raise_for_status()
    except requests.RequestException as e:
        return jsonify({'error': 'Internal processing failed'}), 502

    return jsonify({'imported': len(records), 'status': 'queued'}), 202


@app.route('/api/v1/fetch-config', methods=['POST'])
def fetch_remote_config():
    """Fetch configuration from a specified URL for dynamic partner onboarding"""
    data = request.get_json(force=True)
    url = data.get('url')
    if not url:
        return jsonify({'error': 'url field required'}), 400

    # Basic protocol check
    if not url.startswith(('http://', 'https://')):
        return jsonify({'error': 'Only HTTP(S) URLs supported'}), 400

    try:
        resp = requests.get(url, timeout=10, allow_redirects=False)
        config_data = resp.text
    except requests.RequestException as e:
        return jsonify({'error': f'Failed to fetch: {str(e)}'}), 502

    return jsonify({'config': config_data, 'status_code': resp.status_code}), 200


@app.route('/api/v1/webhook', methods=['POST'])
def receive_webhook():
    """Receive signed webhooks from payment processor"""
    signature = request.headers.get('X-Webhook-Signature', '')
    raw = request.get_data()

    if not verify_webhook_signature(raw, signature):
        abort(401)

    payload = request.get_json(force=True)
    event_type = payload.get('event')
    # Process webhook event
    return jsonify({'received': event_type}), 200


@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'timestamp': time.time()})


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8000)
